#define _GNU_SOURCE
#include <sys/auxv.h>
#include <unistd.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>
int main(int argc, char **argv) {
  const char *p = (const char *)getauxval(AT_EXECFN);
  char path[64], out[4096];
  snprintf(path, sizeof(path), "/proc/%ld/exe", (long)getpid());
  errno = 0;
  ssize_t n = readlink(path, out, sizeof(out)-1);
  int e = errno;
  printf("auxv_matches_absolute_invocation=%d\n", argc > 0 && p && argv[0][0] == '/' && strcmp(p, argv[0]) == 0);
  printf("own_readlink_result=%ld errno=%d\n", (long)n, e);
  return p ? 0 : 1;
}
